function buildSharedCss(W, cfg) {
  return (
    // Spin animation for loading spinner
    "@keyframes zcc-spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}" +
    // CSS-only ring spinner — rendered as the sole button child during loading
    W + " .zcc-spinner{display:block !important;width:18px !important;height:18px !important;border-radius:50% !important;" +
      "border:2.5px solid rgba(255,255,255,0.35) !important;border-top-color:#fff !important;" +
      "animation:zcc-spin 0.7s linear infinite !important;flex-shrink:0 !important}" +
    // Button icon/label structure
    W + " .zcc-btn-icon{display:inline-flex !important;align-items:center !important;flex-shrink:0 !important}" +
    W + " .zcc-btn-icon svg{width:17px !important;height:17px !important;display:block !important}" +
    W + " .zcc-btn-label{display:inline !important}" +
    // Loading state: button already has display:flex + justify-content:center from .zcc-btn,
    // so the lone .zcc-spinner child is automatically centred — just remove the gap
    W + " .zcc-btn--loading{gap:0 !important}" +
    // Section grouping — info group card with subtle background
    W + " .zcc-section-divider{height:1px !important;background:rgba(0,0,0,0.06) !important;margin:10px 0 !important;border:none !important}" +
    W + " .zcc-info-group{display:flex !important;flex-direction:column !important;gap:7px !important;background:#f7faf7 !important;border:1px solid #e8f0e8 !important;border-radius:10px !important;padding:10px 12px !important}" +
    W + " .zcc-badges-row{display:flex !important;flex-wrap:wrap !important;align-items:center !important;gap:6px !important}" +
    // Result card layout — small inline icon, no circle background
    W + " .zcc-result-icon{flex-shrink:0 !important;width:18px !important;height:18px !important;display:flex !important;align-items:center !important;justify-content:center !important;box-sizing:content-box !important;margin-top:1px !important}" +
    W + " .zcc-result-icon svg{width:18px !important;height:18px !important;display:block !important}" +
    W + " .zcc-result-content{flex:1 !important;min-width:0 !important;margin:0 !important;padding:0 !important}" +
    W + " .zcc-result-message{font-size:14px !important;font-weight:700 !important;line-height:1.4 !important;margin:0 !important;padding:0 !important}" +
    W + " .zcc-result.ok .zcc-result-icon{background:none !important;border-radius:0 !important;padding:0 !important}" +
    W + " .zcc-result.ok .zcc-result-message{color:" + cfg.successColor + " !important}" +
    W + " .zcc-result.fail .zcc-result-icon{background:none !important;border-radius:0 !important;padding:0 !important}" +
    W + " .zcc-result.fail .zcc-result-message{color:" + cfg.errorColor + " !important}" +
    // Meta info rows (ETA, zone, days, cutoff)
    W + " .zcc-meta{margin-top:0 !important;font-size:13px !important;display:flex !important;align-items:center !important;gap:7px !important;color:#4b5563 !important;line-height:1.4 !important}" +
    W + " .zcc-meta svg{width:14px !important;height:14px !important;flex-shrink:0 !important;opacity:0.65 !important}" +
    W + " .zcc-meta strong{font-weight:600 !important;color:" + cfg.textColor + " !important}" +
