    "#" + WID + "-panel .zcc-panel-close:hover{opacity:1 !important;background:#f6f6f7 !important}" +
    "#" + WID + "-trigger{" +
      "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
      "border-radius:50px !important;padding:14px 22px !important;font-size:14px !important;font-weight:600 !important;" +
