    "}" +
    "#" + WID + "-trigger:hover{transform:scale(1.03) !important;box-shadow:0 6px 20px " + cfg.primaryColor + "50 !important}" +
    "@media(max-width:420px){#" + WID + "-panel{width:calc(100vw - 32px) !important;max-width:none !important}#" + WID + "-float{left:16px !important;right:16px !important;align-items:stretch !important}}";

  var floatStyle = document.createElement("style");
  floatStyle.textContent = floatCss;
  document.head.appendChild(floatStyle);

  // Build floating shell
  var floatEl = document.createElement("div");
  floatEl.id = WID + "-float";
  floatEl.innerHTML =
    '<div id="' + WID + '-panel" class="zcc-hidden">' +
      '<div class="zcc-panel-header">' +
        '<span class="zcc-panel-title">' +
          '<svg viewBox="0 0 24 24" fill="none" stroke="' + escAttr(cfg.primaryColor) + '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:18px;height:18px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
          ' Delivery Check</span>' +
        '<button class="zcc-panel-close" id="' + WID + '-close" type="button" aria-label="Close">' +
          '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:18px;height:18px"><path d="M18 6L6 18"/><path d="M6 6l12 12"/></svg>' +
        '</button>' +
      '</div>' +
      '<div id="' + WID + '" data-zcc-widget="true" style="border:none !important;box-shadow:none !important;max-width:none !important;padding:16px 20px 20px !important;overflow-y:auto !important;max-height:calc(70vh - 56px) !important">' +
        buildWidgetInner(WID, cfg, cfg.buttonText, false) +
      '</div>' +
    '</div>' +
    '<button id="' + WID + '-trigger" type="button">' +
