  // Uses cfg.buttonText (e.g. "Check") — NOT cfg.heading to avoid a third copy of the heading text
  container.innerHTML =
    '<button id="' + WID + '-popup-trigger" type="button">' +
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:16px;height:16px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
      esc(cfg.buttonText || "Check") +
    '</button>';

  // Overlay + modal append to body
  var overlay = document.createElement("div");
  overlay.id = WID + "-overlay";
  overlay.innerHTML =
    '<div id="' + WID + '-modal">' +
      '<div class="zcc-modal-header">' +
        '<span class="zcc-modal-title">' +
          '<svg viewBox="0 0 24 24" fill="none" stroke="' + escAttr(cfg.primaryColor) + '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:18px;height:18px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
          ' ' + esc(cfg.heading) + '</span>' +
        '<button class="zcc-modal-close" id="' + WID + '-modal-close" type="button" aria-label="Close">' +
          '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:18px;height:18px"><path d="M18 6L6 18"/><path d="M6 6l12 12"/></svg>' +
        '</button>' +
      '</div>' +
      '<div id="' + WID + '" data-zcc-widget="true" style="border:none !important;box-shadow:none !important;max-width:none !important;padding:16px 24px 24px !important;overflow-y:auto !important;max-height:calc(70vh - 60px) !important;border-radius:0 0 16px 16px !important">' +
        buildWidgetInner(WID, cfg, cfg.buttonText, false) +
      '</div>' +
    '</div>';
  document.body.appendChild(overlay);

  var trigger = document.getElementById(WID + "-popup-trigger");
  var closeBtn = document.getElementById(WID + "-modal-close");
  var modal = document.getElementById(WID + "-modal");

  function openPopup() { overlay.classList.add("zcc-open"); }
  function closePopup() { overlay.classList.remove("zcc-open"); }

