                  <path d="M18 6L6 18" /><path d="M6 6l12 12" />
                </svg>
              </button>
            </div>
            {/* Panel body */}
            <div style={{ padding: "12px 14px 14px" }}>
              <style dangerouslySetInnerHTML={{ __html: `#${wid} .zcc-heading{display:none}` }} />
              {widgetHtml}
