44	// ---------------------------------------------------------------------------
45	// Loader
46	// ---------------------------------------------------------------------------
47	
48	export const loader = async ({ request }: LoaderFunctionArgs) => {
49	  const { session, admin } = await authenticate.admin(request);
50	  const shop = session.shop;
51	
52	  const [subscription, zipCount, deliveryRuleCount, waitlistCount, blockedZipCount, shopSettings, shopResponse] = await Promise.all([
53	    getShopSubscription(shop),
54	    db.zipCode.count({ where: { shop } }),
55	    db.deliveryRule.count({ where: { shop } }),
56	    db.waitlistEntry.count({ where: { shop } }),
57	    db.zipCode.count({ where: { shop, type: "blocked" } }),
58	    db.shopSettings.findUnique({ where: { shop } }),
59	    admin.graphql(`{ shop { name } }`),
60	  ]);
61	
62	  const shopData = await shopResponse.json() as { data?: { shop?: { name?: string } } };
63	  const shopName: string = shopData.data?.shop?.name ?? shop.replace(".myshopify.com", "");
64	
65	  await db.shopSettings.upsert({
66	    where: { shop },
67	    create: { shop, shopName },
68	    update: { shopName },
69	  });
70	
71	  const checkUsage = await getMonthlyCheckUsage(shop, subscription.planTier);
72	
73	  return {
74	    subscription,
75	    zipCount,
76	    deliveryRuleCount,
77	    waitlistCount,
78	    blockedZipCount,
79	    checkUsage,
80	    shop,
81	    shopName,
82	    defaultBehavior: shopSettings?.defaultBehavior ?? "block",
83	    notificationEmail: shopSettings?.notificationEmail ?? "",
84	    emailSenderName: shopSettings?.emailSenderName ?? "",
85	    emailReplyTo: shopSettings?.emailReplyTo ?? "",
86	  };
87	};
88	
89	// ---------------------------------------------------------------------------
90	// Action
91	// ---------------------------------------------------------------------------
92	
93	export const action = async ({ request }: ActionFunctionArgs) => {
94	  const { session } = await authenticate.admin(request);
95	  const shop = session.shop;
96	
97	  const formData = await request.formData();
98	  const intent = formData.get("intent") as string;
99	
100	  try {
101	    if (intent === "save-behavior") {
102	      const defaultBehavior = formData.get("defaultBehavior") as string;
103	      if (defaultBehavior !== "block" && defaultBehavior !== "allow") {
104	        return { error: "Invalid value for defaultBehavior" };
105	      }
106	      await db.shopSettings.upsert({
107	        where: { shop },
108	        create: { shop, defaultBehavior },
109	        update: { defaultBehavior },
110	      });
111	      return { success: true, intent };
112	    }
113	
114	    if (intent === "save-email-all") {
115	      // Unified email-settings save — covers notificationEmail, sender name,
116	      // reply-to in a single transaction so concurrent fetchers can't race.
117	      const notificationEmail =
118	        ((formData.get("notificationEmail") as string | null) ?? "").trim() || null;
119	      const emailSenderName =
120	        (formData.get("emailSenderName") as string | null)?.trim() || null;
121	      const emailReplyTo =
122	        (formData.get("emailReplyTo") as string | null)?.trim() || null;
123	
124	      if (notificationEmail && notificationEmail.length > 254) {
125	        return { error: "Notification email is too long." };
126	      }
127	      if (notificationEmail && !/^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,24}$/.test(notificationEmail)) {
128	        return { error: "Enter a valid notification email address." };
129	      }
130	      if (emailReplyTo && !/^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,24}$/.test(emailReplyTo)) {
131	        return { error: "Enter a valid reply-to email address." };
132	      }
133	
134	      await db.shopSettings.upsert({
135	        where: { shop },
136	        create: { shop, notificationEmail, emailSenderName, emailReplyTo },
137	        update: { notificationEmail, emailSenderName, emailReplyTo },
138	      });
139	      return { success: true, intent };
140	    }
141	
142	    if (intent === "send-test-email") {
143	      const testEmail = (formData.get("testEmail") as string | null) ?? "";
144	      if (!testEmail) return { error: "No email address provided." };
145	      if (!isEmailConfigured()) {
146	        return { error: "Email is not configured — RESEND_API_KEY environment variable is missing. Add it to your .env file and redeploy." };
147	      }
148	      const settings = await db.shopSettings.findUnique({ where: { shop } });
149	      const sent = await sendTestEmail(
150	        testEmail,
151	        { senderName: settings?.emailSenderName, shopDisplayName: settings?.shopName, replyTo: settings?.emailReplyTo },
152	        shop,
153	      );
154	      return sent
155	        ? { success: true, intent }
156	        : { error: "Failed to send test email via Resend. Verify your RESEND_API_KEY is valid and your sender domain is verified in the Resend dashboard." };
157	    }
158	
159	    return { error: "Unknown intent" };
160	  } catch (err) {
161	    console.error("[app.settings] action failed shop=%s intent=%s:", shop, intent, err);
162	    return { error: "Failed to save settings. Please try again." };
163	  }
164	};
